mapper.update:
UPDATE t_mp_proc_version
   SET IS_NATURAL_MONTH = #{isNaturalMonth,jdbcType=DECIMAL},
       PRODUCTION_START_DATE = #{productionStartDate,jdbcType=DATE},
       PRODUCTION_END_DATE = #{productionEndDate,jdbcType=DATE}
 WHERE FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{year,jdbcType=DECIMAL}
   AND MONTH = #{month,jdbcType=DECIMAL}
   AND MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
   AND PRODUCTION_VERSION = #{productionVersion,jdbcType=VARCHAR}

mapper.select:
SELECT FACTORY_CODE,
       YEAR,
       MONTH,
       PRODUCT_CODE
  FROM t_mdm_factory_no_production
 WHERE IFNULL(IS_DELETE, 0) = 0
   AND FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{year,jdbcType=DECIMAL}
   AND MONTH = #{month,jdbcType=DECIMAL}

