mapper.select:
SELECT PRODUCT_CODE,
       AVERAGE_VALUE
  FROM (SELECT DISTINCT PRODUCT_CODE,
               SUM(AVERAGE_VALUE) AS AVERAGE_VALUE
          FROM t_mdm_stock_up_plan
         WHERE IFNULL(IS_DELETE, 0) = 0
           AND FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
           AND YEAR = #{year,jdbcType=DECIMAL}
           AND MONTH = #{month,jdbcType=DECIMAL}
         GROUP BY PRODUCT_CODE
       ) A
 WHERE A.AVERAGE_VALUE >= #{averageValue,jdbcType=DECIMAL}

SELECT DISTINCT mprp.PRODUCT_CODE,
       tmmp.MIN_QTY
  FROM t_mp_product_require_plan mprp
  LEFT JOIN t_mdm_min_prod tmmp
    ON tmmp.FACTORY_CODE = mprp.FACTORY_CODE
   AND tmmp.PRODUCT_CODE = mprp.PRODUCT_CODE
   AND IFNULL(tmmp.IS_DELETE, 0) = 0
 WHERE IFNULL(mprp.IS_DELETE, 0) = 0
   AND mprp.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND mprp.`YEAR` = #{year,jdbcType=DECIMAL}
   AND mprp.`MONTH` = #{month,jdbcType=DECIMAL}
   AND mprp.MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
